hooks.command:
python3 -c "
import sys, json, subprocess
data = json.load(sys.stdin)
path = data.get('tool_input', {}).get('file_path', '')
if path and path.endswith('.py') and '__pycache__' not in path:
    for tool in [['poetry', 'run', 'black', '--quiet', path], ['poetry', 'run', 'isort', '--quiet', path]]:
        r = subprocess.run(tool, capture_output=True, text=True)
        if r.returncode != 0:
            print(f'[hook] {tool[2]}: {r.stderr.strip()}', file=sys.stderr)
"
